-- Documentation (tutoriels admin + publics) migrée du disque vers la BD,
-- éditable dans l'admin. Contenu Markdown, bilingue (en retombe sur fr).
CREATE TABLE `docs` (
	`slug` varchar(50) NOT NULL,
	`locale` varchar(2) NOT NULL DEFAULT 'fr',
	`title` varchar(255) NOT NULL,
	`content` longtext NOT NULL,
	`is_public` tinyint NOT NULL DEFAULT 0,
	`updated_at` datetime NOT NULL,
	`updated_by` int,
	CONSTRAINT `docs_pk` PRIMARY KEY(`slug`,`locale`)
);--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('cours', 'fr', 'Gestion des cours', '# Gestion des cours\n\nCe guide explique comment gérer les cours dans le panneau d''administration. Vous pouvez ajouter, modifier, supprimer et filtrer les cours associés aux réservations.\n\n## 1. Accès au panneau des cours\n\n1.  Accédez à la page d''administration.\n2.  Cliquez sur l''onglet **Cours**.\n\n## 2. Tableau des cours\n\nLe tableau affiche tous les cours du module de réservation. Chaque ligne représente un cours avec :\n*   **Nom** : Le nom complet du cours.\n*   **Code du cours** : Le code unique du cours.\n*   **Actions** : Les options pour modifier ou supprimer le cours.\n\n## 3. Ajouter un cours\n\nLe bouton **Ajouter** permet de créer un nouveau cours dans le système.\n\n![Bouton ajout cours](/api/admin/images/cours/ajout_cours.png)\n\n### Procédure d''ajout\n\n1.  Cliquez sur le bouton **Ajouter**.\n2.  Remplissez les champs **Nom** et **Code**.\n3.  Cliquez sur **Ajouter le cours** pour confirmer.\n\n![Confirmation ajout](/api/admin/images/cours/conf_ajout_cours.png)\n\n## 4. Modifier un cours\n\nVous pouvez mettre à jour le nom ou le code d''un cours existant.\n\n### Procédure de modification\n\n1.  Cliquez sur l''icône de **crayon** dans la colonne Actions.\n\n![Modification cours](/api/admin/images/cours/btn_modif_cours.png)\n\n2.  Effectuez les changements nécessaires dans le formulaire.\n3.  Cliquez sur **Enregistrer les modifications**.\n\n![Confirmation modification](/api/admin/images/cours/conf_modif_cours.png)\n\n## 5. Supprimer un cours\n\nLa suppression retire définitivement le cours du système.\n\n### Procédure de suppression\n\n1.  Cliquez sur l''icône de **poubelle** dans la colonne Actions.\n\n![Suppression cours](/api/admin/images/cours/btn_del_cours.png)\n\n2.  Lisez attentivement l''avertissement.\n3.  Cliquez sur **Confirmer la suppression**.\n\n![Confirmation suppression](/api/admin/images/cours/conf_del_cours.png)\n\n## 6. Filtrage et rafraîchissement\n\n### Filtrer la liste\nUtilisez la barre de recherche pour trouver rapidement un cours par son nom ou son code.\n\n![Barre de recherche](/api/admin/images/cours/search-bar_cours.png)\n\n### Actualiser les données\nUtilisez le bouton de rafraîchissement pour mettre à jour manuellement la liste des cours.\n\n![Bouton rafraîchissement](/api/admin/images/cours/btn_refresh_cours.png)', 0, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('disponibilites', 'fr', 'Gestion des disponibilités', '# Gestion des disponibilités\n\nCe guide explique comment définir les plages horaires d''ouverture du laboratoire LUDOV. Le système fonctionne avec deux types de disponibilités : les horaires hebdomadaires récurrents et les ouvertures spécifiques.\n\n## 1. Disponibilités par semaine (récurrent)\n\nL''onglet **Par semaine** permet de définir l''horaire standard qui se répète chaque semaine.\n\n![Vue d''ensemble de la semaine](/api/admin/images/disponibilites/semaine.png)\n\n### Configuration des jours\n\n1.  **Activation des jours** : Utilisez les interrupteurs (toggles) pour activer ou désactiver chaque jour de la semaine. Un jour désactivé signifie que le laboratoire est fermé.\n2.  **Plages horaires** : Pour chaque jour activé, définissez les heures d''ouverture (ex: 9h00 à 17h00). Vous pouvez ajouter plusieurs plages pour une même journée (ex: matin et après-midi).\n\n![Configuration hebdomadaire](/api/admin/images/disponibilites/semaine-hebdomadaire.png)\n\n### Période de validité\n\nVous pouvez définir pour quelle période cet horaire hebdomadaire est valide :\n*   **Toujours valide** : L''horaire s''applique indéfiniment.\n*   **Plage de dates** : L''horaire ne s''applique que pour une période donnée (ex: Session Automne 2025).\n\n![Option de validité](/api/admin/images/disponibilites/semaine-disponibilite-toujours.png)\n\n### Exceptions (Blocage)\n\nLes exceptions dans cet onglet servent à **bloquer** des plages horaires pour des dates précises (ex: jour férié, absence du responsable).\n*   Sélectionnez une date spécifique.\n*   Indiquez les heures où le laboratoire sera fermé exceptionnellement, malgré l''horaire hebdomadaire.\n\n![Exceptions de la semaine](/api/admin/images/disponibilites/semaine-exceptions.png)\n\n## 2. Disponibilités spécifiques (ouvertures supplémentaires)\n\nL''onglet **Dates spécifiques** est utilisé pour ajouter des ouvertures ponctuelles qui ne font pas partie de l''horaire régulier (ex: ouverture spéciale fin de session, fin de semaine de jam).\n\n![Sélection dates spécifiques](/api/admin/images/disponibilites/specifique-selection.png)\n\n1.  Sélectionnez la ou les dates désirées dans le calendrier.\n2.  Définissez les plages horaires d''ouverture pour ces dates.\n\n![Configuration spécifique](/api/admin/images/disponibilites/specifique.png)\n\nCes disponibilités s''ajoutent à l''horaire hebdomadaire existant.\n\n## Enregistrement\n\nN''oubliez pas de sauvegarder vos modifications en cliquant sur le bouton de confirmation pour qu''elles soient prises en compte par le système de réservation.\n', 0, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('politique', 'fr', 'Gestion de la politique de confidentialité', '# Gestion de la politique de confidentialité\n\nCe guide explique comment modifier la politique de confidentialité de l''application LUDOV. Cette politique est visible par tous les utilisateurs et lors de l''inscription.\n\n## 1. Accès à l''éditeur\n\n1.  Accédez à la page d''administration.\n2.  Cliquez sur l''onglet **Politique de confidentialité**.\n\n![Interface de gestion de la politique](/api/admin/images/politique/politique.png)\n\n## 2. Modifier le contenu\n\nL''interface propose un éditeur de texte riche pour la mise en forme.\n\n### Fonctionnalités de l''éditeur\n*   Mise en forme (gras, italique, souligné).\n*   Titres et listes.\n*   Liens et images.\n\n### Mise à jour automatique de la date\nLa date de "Dernière mise à jour" affichée en haut de l''éditeur sera automatiquement actualisée à la date d''aujourd''hui lors de l''enregistrement.\n\n## 3. Enregistrer les modifications\n\nUne fois vos modifications terminées :\n\n1.  Cliquez sur le bouton **Enregistrer** (bleu).\n2.  Confirmez la sauvegarde.\n\n> **Attention** : Les modifications sont appliquées immédiatement et sont visibles par tous les utilisateurs.\n\nSi vous souhaitez annuler vos modifications en cours sans sauvegarder, cliquez sur le bouton **Annuler** (gris).\n', 0, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('reservations', 'fr', 'Gestion des réservations', '# Gestion des réservations\n\nCe guide explique comment gérer les réservations dans le panneau d''administration. Vous pouvez consulter l''historique, voir les détails complets et annuler des réservations.\n\n## 1. Accès au panneau des réservations\n\n1.  Accédez à la page d''administration.\n2.  Cliquez sur l''onglet **Réservations**.\n\n## 2. Tableau des réservations\n\nLe tableau affiche toutes les réservations du système. Chaque ligne représente une réservation avec :\n*   **Utilisateur** : Le nom de l''utilisateur ayant effectué la réservation.\n*   **Console** : La plateforme réservée.\n*   **Jeux** : La liste des jeux sélectionnés.\n*   **Date et Heure** : Le moment prévu pour la réservation.\n*   **Station** : La station assignée.\n*   **Statut** : L''état actuel (À venir, Passée, Annulée).\n*   **Actions** : Les options pour voir les détails ou supprimer.\n\n### Recherche et rafraîchissement\n*   Utilisez la barre de recherche pour trouver une réservation par nom d''utilisateur.\n*   Utilisez le bouton de rafraîchissement pour actualiser la liste manuellement.\n\n![Recherche](/api/admin/images/reservations/recherche.png)\n\n![Rafraîchissement](/api/admin/images/reservations/refresh.png)\n\n## 3. Afficher les détails\n\nPour consulter les informations complètes d''une réservation, cliquez sur l''icône d''**œil** dans la colonne Actions ou directement sur la ligne de la réservation.\n\n![Actions](/api/admin/images/reservations/actions.png)\n\nLa page de détails affiche :\n*   Les informations de l''utilisateur.\n*   Le statut de la réservation.\n*   La console, les jeux et les accessoires réservés.\n*   Le cours associé (si applicable).\n\n![En-tête des détails](/api/admin/images/reservations/details-entete.png)\n\n![Détails complets](/api/admin/images/reservations/details.png)\n\n## 4. Supprimer une réservation\n\nLa suppression annule la réservation et libère la plage horaire si elle est à venir.\n\n### Procédure de suppression\n\n1.  Cliquez sur l''icône de **poubelle** dans la colonne Actions.\n2.  Confirmez la suppression dans la fenêtre contextuelle.\n\n> **Attention** : Cette action est irréversible.\n\n![Suppression](/api/admin/images/reservations/suppression.png)\n\n## 5. Métriques\n\nLes métriques en haut du tableau affichent :\n*   Nombre total de réservations.\n*   Nombre de réservations à venir.\n*   Nombre de réservations passées.\n\n![Métriques](/api/admin/images/reservations/metriques.png)\n', 0, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('stations', 'fr', 'Gestion des stations', '# Gestion des stations\n\nCe guide explique comment gérer les stations de jeu dans le panneau d''administration. Vous pouvez ajouter, modifier et supprimer des stations, ainsi que gérer les consoles associées.\n\n## 1. Accès au panneau des stations\n\n1.  Accédez à la page d''administration.\n2.  Cliquez sur l''onglet **Stations**.\n\n## 2. Tableau des stations\n\nLe tableau affiche toutes les stations du système. Chaque ligne représente une station avec :\n*   **Nom de la station** : Le nom complet.\n*   **Date de création** : La date d''ajout au système.\n*   **Statut** : Vert pour active, rouge pour inactive.\n*   **Actions** : Les options pour modifier ou supprimer.\n\n### Recherche et rafraîchissement\n*   Utilisez la barre de recherche pour trouver une station spécifique.\n*   Utilisez le bouton de rafraîchissement pour actualiser la liste.\n\n![Recherche et rafraîchissement](/api/admin/images/stations/Recherche_Station.png)\n\n## 3. Ajouter une station\n\nLe bouton **Ajouter une nouvelle station** permet de créer une station.\n\n![Ajout station](/api/admin/images/stations/Ajout_Station.png)\n\n### Procédure d''ajout\n\n1.  Cliquez sur **Ajouter une nouvelle station**.\n2.  Entrez le nom de la station.\n3.  Sélectionnez les consoles associées et cliquez sur **Ajouter** pour chacune.\n4.  Cliquez sur le bouton **Ajouter** final pour créer la station.\n\n![Ajout console](/api/admin/images/stations/Ajouter_Console_Station.png)\n\n## 4. Modifier une station\n\nVous pouvez mettre à jour le nom, les consoles associées et le statut d''une station.\n\n### Procédure de modification\n\n1.  Cliquez sur le bouton **Modifier** d''une station.\n2.  Mettez à jour le nom si nécessaire.\n3.  Ajoutez ou supprimez des consoles associées.\n4.  Cochez ou décochez **Active** pour changer le statut.\n5.  Cliquez sur **Modifier** pour enregistrer.\n\n![Modification station](/api/admin/images/stations/Station_Active.png)\n\n## 5. Supprimer une station\n\nLa suppression retire définitivement la station du système.\n\n### Procédure de suppression\n\n1.  Cliquez sur le bouton **Supprimer** d''une station.\n2.  Confirmez la suppression dans la fenêtre contextuelle.\n\n![Suppression station](/api/admin/images/stations/Suppression_Station.png)\n\n## 6. Métriques\n\nLes métriques en haut du tableau affichent :\n*   Nombre de stations actives.\n*   Nombre de stations inactives.\n*   Station la plus réservée.\n\n![Métriques](/api/admin/images/stations/Metriques_Station.png)', 0, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('utilisateurs', 'fr', 'Gestion des utilisateurs', '# Gestion des utilisateurs\n\nCe guide explique comment gérer les comptes utilisateurs dans le panneau d''administration. Vous pouvez ajouter, modifier, supprimer et réinitialiser les mots de passe des utilisateurs.\n\n## 1. Accès au panneau des utilisateurs\n\n1.  Accédez à la page d''administration.\n2.  Cliquez sur l''onglet **Utilisateurs**.\n\n## 2. Tableau des utilisateurs\n\nLe tableau affiche tous les utilisateurs inscrits. Chaque ligne représente un utilisateur avec :\n*   **Email** : L''adresse courriel.\n*   **Nom** : Le nom complet.\n*   **Rôle** : Administrateur ou Utilisateur.\n*   **Date de création** : La date d''inscription.\n*   **Actions** : Les options pour gérer le compte.\n\n### Métriques\nEn haut du tableau, vous trouverez :\n*   Le nombre total d''utilisateurs.\n*   Le nombre d''utilisateurs non configurés (sans mot de passe).\n*   Le nombre d''utilisateurs ayant effectué des réservations.\n\n![Métriques utilisateurs](/api/admin/images/utilisateurs/metrics_users.png)\n\n## 3. Ajouter un utilisateur\n\nLe bouton **Ajouter** permet de créer un ou plusieurs comptes.\n\n![Bouton ajout](/api/admin/images/utilisateurs/ajout.png)\n\n### Ajout simple\n1.  Cliquez sur **Ajouter** puis **Ajouter un utilisateur**.\n2.  Remplissez le prénom, le nom et le courriel.\n3.  Cochez **Administrateur** si nécessaire.\n4.  Cliquez sur **Ajouter l''utilisateur**.\n\n![Ajout simple](/api/admin/images/utilisateurs/ajout_simple.png)\n\n### Ajout multiple (CSV)\n1.  Cliquez sur **Ajouter**.\n2.  Glissez un fichier CSV dans la zone dédiée ou cliquez pour sélectionner un fichier.\n3.  Assurez-vous que le format du fichier est respecté.\n\n![Ajout multiple](/api/admin/images/utilisateurs/ajout_multiple.png)\n\n## 4. Afficher les détails\n\nCliquez sur une ligne du tableau pour voir les détails complets d''un utilisateur, y compris son historique de réservation.\n\n![Détails utilisateur](/api/admin/images/utilisateurs/details.png)\n\n## 5. Réinitialiser le mot de passe\n\nCette action force l''utilisateur à choisir un nouveau mot de passe à sa prochaine connexion.\n\n### Procédure de réinitialisation\n1.  Cliquez sur l''icône de **clé** dans la colonne Actions.\n2.  Confirmez l''action dans la fenêtre contextuelle.\n\n![Réinitialisation mot de passe](/api/admin/images/utilisateurs/btn_reset_mdp.png)\n\n## 6. Supprimer un utilisateur\n\nLa suppression retire définitivement le compte et ses données associées.\n\n### Procédure de suppression\n1.  Cliquez sur l''icône de **poubelle** dans la colonne Actions.\n2.  Lisez l''avertissement et confirmez la suppression.\n\n![Suppression utilisateur](/api/admin/images/utilisateurs/btn_delete.png)\n\n## 7. Filtrage et rafraîchissement\n\n### Filtrer la liste\nUtilisez la barre de recherche pour trouver un utilisateur par nom ou courriel.\n\n![Barre de recherche](/api/admin/images/utilisateurs/search-bar_users.png)\n\n### Actualiser les données\nUtilisez le bouton de rafraîchissement pour mettre à jour la liste manuellement.\n\n![Bouton rafraîchissement](/api/admin/images/utilisateurs/refresh.png)', 0, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('connexion', 'fr', 'Connexion à la plateforme', '# Guide de connexion et création de compte\n\nCe guide explique comment activer votre compte et vous connecter à la plateforme de réservation LUDOV.\n\n> **Restriction d''accès**\n> La création de compte est strictement réservée aux **étudiants vérifiés de l''Université de Montréal** inscrits à un cours lié aux jeux vidéo.\n>\n> Les adresses courriel autorisées sont pré-enregistrées dans le système. Vous ne pouvez pas créer de compte si votre adresse courriel n''a pas été préalablement autorisée par l''administration.\n\n---\n\n## 1. Activation de votre compte (Première connexion)\n\nSi c''est votre première visite, vous devez activer votre compte en suivant ces étapes.\n\n### Étape 1 : Ouverture de la page de première connexion\n\nRendez-vous sur la page de connexion et cliquez sur le bouton "Première connexion ?".\n\n![Première connexion](/images/tutoriels/connexion/connexion.png)\n\n### Étape 2 : Saisie du courriel\n\nEntrez votre adresse courriel institutionnelle (celle fournie par l''université).\n\n![Saisie du courriel](/images/tutoriels/connexion/inscription.png)\n\n> **Conditions d''utilisation**\n> En créant un compte et en vous connectant à la plateforme, vous acceptez implicitement les **conditions d''utilisation** et la politique de confidentialité de LUDOV.\n\n### Étape 3 : Vérification du code (OTP)\n\nUn code de vérification à 6 chiffres sera envoyé à votre adresse courriel. Consultez votre boîte de réception (et vos indésirables) pour le trouver, puis saisissez-le dans le formulaire.\n\n![Vérification du code](/images/tutoriels/connexion/otp.png)\n\n### Étape 4 : Création du mot de passe\n\nUne fois votre identité confirmée, vous serez invité à créer votre mot de passe personnel. Choisissez un mot de passe sécurisé.\n\n![Création du mot de passe](/images/tutoriels/connexion/creation-mdp.png)\n\n---\n\n## 2. Connexion standard\n\nUne fois votre compte activé et votre mot de passe défini, vous pourrez vous connecter normalement lors de vos prochaines visites.\n\n1. Entrez votre courriel.\n2. Entrez votre mot de passe.\n3. Cliquez sur "Se connecter".\n\n![Écran de connexion](/images/tutoriels/connexion/connexion.png)\n\n---\n\n## Besoin d''aide ?\n\nSi vous pensez être éligible mais que vous ne parvenez pas à créer votre compte, veuillez contacter votre responsable de cours ou l''administration du laboratoire LUDOV pour vérifier que votre courriel est bien dans la liste des accès autorisés.\n', 1, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('effectuer_reservation', 'fr', 'Effectuer une réservation', '# Guide de réservation d''une station de jeu\n\nCe guide explique comment effectuer une réservation de station de jeu sur la plateforme LUDOV.\n\nLUDOV dispose d''un local équipé de stations (TV HD, Casque VR, etc.) que vous pouvez réserver pour des blocs de 2 heures afin de jouer à un jeu vidéo sur une console spécifique.\n\n---\n\n## Processus de réservation\n\nSuivez ces étapes pour réserver une station de jeu.\n\n### Étape 1 : Sélection de la console\n\nLa première étape consiste à choisir la console que vous souhaitez utiliser.\n\n- Une **barre de recherche** est disponible pour trouver rapidement une console.\n- Seules les consoles disponibles dans le local sont affichées.\n\n![Sélection de la console](/images/tutoriels/effectuer_reservation/console.png)\n\nVous pouvez voir les détails de la console avant de la sélectionner.\n\n![Détails de la console](/images/tutoriels/effectuer_reservation/console-selection.png)\n\n> **Important** : Dès que vous sélectionnez une console, vous disposez de **15 minutes** pour compléter votre réservation. Un minuteur s''affichera pour vous indiquer le temps restant.\n>\n> Il est possible d''annuler le processus de réservation en tout temps si vous changez d''avis.\n\n### Étape 2 : Sélection des jeux\n\nUne fois la console choisie, vous devez sélectionner les jeux auxquels vous souhaitez jouer.\n\n- Seuls les jeux compatibles avec la console sélectionnée sont affichés.\n- Vous pouvez utiliser la **barre de recherche** pour trouver un jeu spécifique.\n- Vous pouvez sélectionner jusqu''à **3 jeux** maximum.\n\n![Liste des jeux](/images/tutoriels/effectuer_reservation/jeux.png)\n\n![Sélection des jeux](/images/tutoriels/effectuer_reservation/jeux-selection.png)\n\n### Étape 3 : Sélection des accessoires\n\nVous pouvez ensuite ajouter des accessoires à votre réservation.\n\n- Seuls les accessoires compatibles avec la console sélectionnée sont affichés.\n- Une **barre de recherche** est disponible.\n- Il n''y a **pas de limite** sur la quantité d''accessoires que vous pouvez réserver (dans la limite des stocks disponibles).\n\n> **Note** : Pour certains jeux, un accessoire peut être requis. Dans ce cas, il sera **pré-sélectionné** automatiquement dans cette page.\n\n![Liste des accessoires](/images/tutoriels/effectuer_reservation/accessoires.png)\n\n![Sélection des accessoires](/images/tutoriels/effectuer_reservation/accessoires-selection.png)\n\n### Étape 4 : Choix de la date et de l''heure\n\nVous devez maintenant choisir le moment de votre réservation.\n\n- Les plages horaires valides sont définies par un administrateur.\n- Les réservations se font toujours par **blocs de 2 heures**.\n- Seules les heures et dates pour lesquelles la console, les jeux et les accessoires sélectionnés sont tous disponibles sont affichées.\n\n![Calendrier](/images/tutoriels/effectuer_reservation/date.png)\n\n![Sélection de l''heure](/images/tutoriels/effectuer_reservation/date-selection.png)\n\n> **Restrictions de réservation** :\n> - Vous ne pouvez pas réserver pour le **jour même** ou le **lendemain**.\n> - Vous ne pouvez pas réserver la **même console** deux fois dans la **même journée**.\n\n### Étape 5 : Sélection du cours\n\nVous devez indiquer pour quel cours universitaire vous effectuez cette réservation.\n\n- Sélectionnez votre cours dans la liste.\n- Si votre cours n''est pas listé ou si la réservation est pour un autre motif académique, vous pouvez sélectionner l''option **"Autre"**.\n\n![Sélection du cours](/images/tutoriels/effectuer_reservation/cours.png)\n\n![Cours sélectionné](/images/tutoriels/effectuer_reservation/cours-selection.png)\n\n### Étape 6 : Confirmation\n\nUne page de détails s''affiche pour récapituler tous vos choix (console, jeux, accessoires, date, heure, cours).\n\nVérifiez attentivement les informations avant de confirmer.\n\n![Confirmation de la réservation](/images/tutoriels/effectuer_reservation/confirmation.png)\n\n### Étape 7 : Réservation confirmée\n\nUne fois la réservation confirmée :\n1. Elle s''affichera sur votre **tableau de bord**.\n2. Vous recevrez un **courriel de confirmation**.\n\n![Réservation confirmée](/images/tutoriels/effectuer_reservation/confirmee.png)\n\n---\n\n## Liens utiles\n\n- [Comment voir les détails de ma réservation](/docs?page=consultation_reservations&adminRessources=false)\n- [Comment activer les rappels par courriel](/docs?page=rappels&adminRessources=false)\n', 1, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('consultation_reservations', 'fr', 'Consulter ses réservations', '# Guide de consultation de vos réservations\n\nCe guide explique comment consulter vos réservations à venir et votre historique sur la plateforme LUDOV. Pour savoir comment effectuer une nouvelle réservation, consultez notre guide dédié : [Effectuer une réservation](/docs?page=effectuer_reservation&adminRessources=false).\n\n---\n\n## Page d''accueil\n\nSur la page d''accueil, vous trouverez deux sections principales :\n\n1.  **Réservations à venir** : Affiche vos réservations futures confirmées.\n2.  **Historique** : Affiche vos réservations passées ainsi que celles qui ont été annulées.\n\n![Réservations à venir](/images/tutoriels/consultation_reservations/reservations-a-venir.png)\n\n![Historique des réservations](/images/tutoriels/consultation_reservations/historique-reservations.png)\n\nLes réservations annulées apparaissent également dans l''historique avec un statut distinct.\n\n![Historique avec réservation annulée](/images/tutoriels/consultation_reservations/historique-reservation-annulee.png)\n\n## Détails d''une réservation\n\nPour voir les détails d''une réservation, cliquez sur le bouton **"Détails"** pour la réservation que vous souhaitez consulter.\n\n### En-tête et options\n\nEn haut de la page de détails, vous trouverez les informations principales (**Date**, **Heure**, **Plateforme**) ainsi que plusieurs options :\n\n-   **Ajouter au calendrier** : Télécharge un fichier `.ics` pour ajouter la réservation à votre calendrier personnel.\n-   **Rappels par courriel** : Permet de configurer des alertes pour ne pas oublier votre réservation. [Voir comment activer les rappels](/docs?page=rappels&adminRessources=false).\n-   **Annuler la réservation** : Permet d''annuler votre réservation si vous ne pouvez plus vous présenter.\n\n![En-tête des détails](/images/tutoriels/consultation_reservations/details-reservation-entete.png)\n\n### Informations de la réservation\n\nLa page de détails liste également tous les éléments inclus dans votre réservation :\n\n-   La **console** réservée.\n-   Les **jeux** sélectionnés.\n-   Les **accessoires** choisis.\n\n![Détails complets](/images/tutoriels/consultation_reservations/details-reservation.png)\n\n## Annuler une réservation\n\nSi vous devez annuler une réservation, cliquez sur le bouton **"Annuler la réservation"** dans la page de détails. Une confirmation vous sera demandée.\n\n![Annulation de réservation](/images/tutoriels/consultation_reservations/annuler-reservation.png)\n', 1, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('rappels', 'fr', 'Rappels de réservation', '# Guide d''activation des rappels par courriel\n\nCe guide explique comment configurer des rappels par courriel pour vos réservations sur la plateforme LUDOV.\n\n---\n\n## Processus d''activation\n\nSuivez ces étapes pour activer les rappels pour une réservation existante.\n\n### Étape 1 : Accéder aux détails de la réservation\n\nDepuis la page d''accueil, dans la section **"Réservations à venir"**, cliquez sur le bouton **"Détails"** de la réservation pour laquelle vous souhaitez recevoir un rappel.\n\n![Liste des réservations à venir](/images/tutoriels/rappels/reservations-a-venir.png)\n\n### Étape 2 : Ouvrir la fenêtre de rappels\n\nDans l''en-tête de la page de détails, cliquez sur le bouton **"Rappels par courriel"**.\n\n![Bouton de rappels dans l''en-tête](/images/tutoriels/rappels/details-reservation-entete.png)\n\n### Étape 3 : Activer les rappels\n\nUne fenêtre s''ouvre. Utilisez le bouton à bascule (toggle) pour activer la fonctionnalité de rappel.\n\n![Fenêtre de configuration des rappels](/images/tutoriels/rappels/rappels.png)\n\n### Étape 4 : Choisir le moment du rappel\n\nUne fois activé, plusieurs options de délai s''affichent (par exemple : 1h avant, 1 jour avant, etc.).\n\n-   Sélectionnez l''option qui vous convient.\n-   Vous ne pouvez choisir qu''**une seule** option à la fois.\n\n![Sélection du délai de rappel](/images/tutoriels/rappels/rappels-actif.png)\n\n### Modification du rappel\n\nUne fois le rappel configuré, vous pouvez le modifier à tout moment en rouvrant la fenêtre de rappels et en sélectionnant une nouvelle option ou en désactivant le rappel.\n\n![Rappel configuré](/images/tutoriels/rappels/details-reservation-entete-rappels-actif.png)\n', 1, NOW());--> statement-breakpoint
INSERT INTO `docs` (`slug`, `locale`, `title`, `content`, `is_public`, `updated_at`) VALUES ('markdown-guide', 'fr', 'Guide Markdown', '# Guide Markdown\n\nCe guide résume la syntaxe Markdown utilisée par l''éditeur de documentation.\n\n## Titres\n\n`# Titre 1`, `## Titre 2`, `### Titre 3` — les titres structurent la page et alimentent la table des matières.\n\n## Mise en forme\n\n- `**gras**` → **gras**\n- `*italique*` → *italique*\n- `` `code` `` → `code`\n\n## Listes\n\n```\n- Élément\n- Élément\n1. Étape\n2. Étape\n```\n\n## Liens et images\n\n```\n[texte du lien](https://exemple.com)\n![description de l''image](/api/admin/images/dossier/image.png)\n```\n\nUtilisez le bouton « Insérer une image » de l''éditeur pour téléverser une image : la référence Markdown est insérée automatiquement.\n\n## Tableaux\n\n```\n| Colonne 1 | Colonne 2 |\n|-----------|-----------|\n| Valeur    | Valeur    |\n```\n\n## Citations\n\n`> Texte cité` produit un bloc de citation.\n', 0, NOW());
